export type SearchConfigResponse = {
  /**
   * Remote repository URL configured
   */
  repository_url?: string;
  /**
   * Username to authenticate connection to the version control system
   */
  username?: string;
  /**
   * Name of the remote branch where objects from this Thoughtspot instance will be versioned.
   */
  commit_branch_name?: string;
  /**
   * Branches that have been pulled in local repository
   */
  branches?: string[];
  /**
   * Maintain mapping of guid for the deployment to an instance
   */
  enable_guid_mapping?: boolean;
  /**
   * Name of the branch where the configuration files related to operations between Thoughtspot and version control repo should be maintained.
   */
  configuration_branch_name?: string;
  /**
   * The current Org context of the user.
   */
  org?: {
    /**
     * The ID of the object.
     */
    id: number;
    /**
     * Name of the object.
     */
    name: string;
    [k: string]: unknown;
  };
  [k: string]: unknown;
}[];

requestType:
/* Request type for updateConfig */

export interface UpdateConfigRequest {
  /**
   * Username to authenticate connection to version control system
   */
  username?: string;
  /**
   * Access token corresponding to the user to authenticate connection to version control system
   */
  access_token?: string;
  /**
   *    Applicable when Orgs is enabled in the cluster
   *
   *
   * List of Org ids or name. Provide value -1 for cluster level. Example : ["OrgID1-or-Name1", "OrgID2-or-Name2"]
   *
   *
   *
   *
   * Note: If no value is specified, then the configurations will be returned for all orgs the user has access to  <br/>  <span class="since-beta-tag">Version: 9.5.0.cl or later</span>
   */
  org_identifier?: string;
  /**
   * List the remote branches to configure. Example:[development, production]
   */
  branch_names?: string[];
  /**
   * Name of the remote branch where objects from this Thoughtspot instance will be versioned. <br/>  <span class="since-beta-tag">Version: 9.7.0.cl or later</span>
   */
  commit_branch_name?: string;
  /**
   * Maintain mapping of guid for the deployment to an instance <br/>  <span class="since-beta-tag">Version: 9.4.0.cl or later</span>
   */
  enable_guid_mapping?: boolean;
  /**
   * Name of the branch where the configuration files related to operations between Thoughtspot and version control repo should be maintained. <br/>  <span class="since-beta-tag">Version: 9.7.0.cl or later</span>
   */
  configuration_branch_name?: string;
  [k: string]: unknown;
}

